    def three(n):
        h, r = divmod(n, 100)
        t, o = divmod(r, 10)
        p = []
        if h:
            p.append('yüz' if h == 1 else ONES[h] + ' yüz')
        if t:
            p.append(TENS[t])
        if o:
            p.append(ONES[o])
        return ' '.join(p)
    def words(n):
        n = int(n)
        if n == 0:
            return 'sıfır'
        p = []
        for size, word in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
            g, n = divmod(n, size)
            if g:
                p.append(word if (g == 1 and word == 'bin') else three(g) + ' ' + word)
        if n:
            p.append(three(n))
        return ' '.join(p)
    def num(x):
