    def suffix_match(said, number):
        if len(said) > len(number):
            return False
        tail = number[len(number) - len(said):]
        return all(a == b or b == '*' for a, b in zip(said, tail))
    def match_card(text, digits):
        pool = cards()
        cand = json.loads(vars.get('cand') or '[]')
        if cand and len(re.sub(r'\D', '', str(digits or ''))) >= 4:
            pool = [c for c in pool if c['num'] in cand]
