            vocab = set()
            for c in pool:
                vocab |= set(tr_lower(c['name']).split())
            said = [w for w in tr_lower(text).split() if w in vocab]
            if not said:
                found = []
            else:
                found = [c for c in pool if all(w in tr_lower(c['name']).split() for w in said)]
                exact = [c for c in found if tr_lower(c['name']).split() == said]
                if exact:
                    found = exact
        if not found:
            line = L['no_digits_match'] if len(d) >= 4 else L['no_such_card'].replace('{names}', ', '.join(label(c) for c in eligible()))
            fail(line + ' ' + L['ask_card_short'])
            return
        if len(found) == 1:
            select(found[0])
            return
        vars['cand'] = json.dumps([c['num'] for c in found])
