        name = vars.get('card_name') or ''
        name_sp = name + ' ' if name else ''
        last4 = digits_say(vars.get('card_last4'))
        td = today()
        due = pdate(b.get('lastPayDate'))
        cut_next = pdate(b.get('nextStatementDate'))
        tl = b.get('debtTL') if isinstance(b.get('debtTL'), dict) else dict()
        parts = []
        if not pdate(b.get('statementDate')):
