                    parts.append(line)
                parts[0] = intro + parts[0]
                if clear:
                    names = [CUR[i][1] for i in clear]
                    lst = names[0] if len(names) == 1 else ', '.join(names[:-1]) + ' ve ' + names[-1]
                    parts.append(L['no_debt_in'].replace('{list}', lst))
                passed = bool(td and due and td > due)
                if passed and str(b.get('automaticPaymentFlag')) == 'Y' and num(tl.get('remainAutomaticPaymentAmount')) > 0:
                    parts.append(L['auto_pay'].replace('{x}', money(tl.get('remainAutomaticPaymentAmount'), 0)))
                if td and due and td == due:
                    parts.append(L['due_today'])
                elif passed:
