                text = ' '.join(parts)
        vars['statement_date'] = str(b.get('statementDate') or '')
        read = json.loads(vars.get('read_cards') or '[]')
        if vars.get('card_number') not in read:
            read.append(vars.get('card_number'))
        vars['read_cards'] = json.dumps(read)
        vars['has_read'] = 'yes'
        more = any(c['num'] not in read for c in eligible())
        vars['nodebt'] = 'yes' if nodebt else 'no'
        if vars.get('also') == 'email' and not nodebt:
            vars['also'] = ''
            st = vars.get('email_status')
            start_email()
            if vars.get('route') != 'close_error':
                vars['say_now'] = text + ' ' + vars['say_now']
        elif more:
            say(text + ' ' + L['another_card'], 'another')
        elif nodebt:
            vars['say_now'] = text
            close('close_read_menu')
        else:
            say(text + ' ' + offer_line(), 'offer')
    pass
