        return [c for c in cards() if c['main']]
    def label(c):
        return c['name'] if c['name'] else 'sonu ' + digits_say(c['last4']) + ' ile biten kart'
    def ask_card_line():
        names = []
        for c in eligible():
            if c['name'] and c['name'] not in names:
                names.append(c['name'])
        if not names:
            return L['ask_card_short']
        return L['ask_card'].replace('{examples}', ' veya '.join(names[:2]))
    def offer_line():
        if vars.get('email_status') == 'yes':
            return L['offer_both']
        return L['offer_week']
    def email_line():
        a = str(vars.get('email') or '')
        local, _, domain = a.partition('@')
        if len(a) <= 30 and re.match(r'^[a-z]+(\.[a-z]+)?$', local):
            spoken = a
        else:
            spoken = local[:1] + ' ile başlayan ' + domain.split('.')[0].capitalize()
            return L['email_ask'].replace('{address} adresine', spoken + ' adresinize')
        return L['email_ask'].replace('{address}', spoken)
    def start_email(prefix=''):
        st = vars.get('email_status')
        if st == 'error':
            close('close_error')
        elif st != 'yes':
            say(L['no_email'] + ' ' + L['offer_week'], 'offer')
        else:
            say((prefix + ' ' if prefix else '') + email_line(), 'email_confirm')
    def start_week(week):
        vars['want_week'] = str(week or '')
        close('week_get')
    def week_options():
        cur = int(num(vars.get('cur_week')))
        opts = [str(w) + '.' for w in WEEKS if w != cur]
        text = ', '.join(opts[:-1]) + ' ya da ' + opts[-1]
        return L['week_options'].replace('{options}', text)
    def select(c):
        if not c['main']:
            fail(L['not_eligible'] + ' ' + ask_card_line())
            return
        vars['card_number'] = c['num']
        vars['card_last4'] = c['last4']
        vars['card_name'] = c['name']
        vars['cand'] = ''
        close('balance')
    def suffix_match(said, number):
        if len(said) > len(number):
            return False
        tail = number[len(number) - len(said):]
        return all(a == b or b == '*' for a, b in zip(said, tail))
    def match_card(text, digits):
        pool = cards()
        cand = json.loads(vars.get('cand') or '[]')
        if cand and len(re.sub(r'\D', '', str(digits or ''))) >= 4:
            pool = [c for c in pool if c['num'] in cand]
        d = re.sub(r'\D', '', str(digits or ''))
        if len(d) >= 4:
            found = [c for c in pool if suffix_match(d, c['num'])]
        else:
            vocab = set()
            for c in pool:
                vocab |= set(tr_lower(c['name']).split())
            said = [w for w in tr_lower(text).split() if w in vocab]
            if not said:
                found = []
            else:
                found = [c for c in pool if all(w in tr_lower(c['name']).split() for w in said)]
                exact = [c for c in found if tr_lower(c['name']).split() == said]
                if exact:
                    found = exact
        if not found:
            line = L['no_digits_match'] if len(d) >= 4 else L['no_such_card'].replace('{names}', ', '.join(label(c) for c in eligible()))
            fail(line + ' ' + L['ask_card_short'])
            return
        if len(found) == 1:
            select(found[0])
            return
        vars['cand'] = json.dumps([c['num'] for c in found])
        if len(set(c['name'] for c in found)) > 1:
            line, new = L['which_of'].replace('{names}', ' ya da '.join(label(c) for c in found)), 'card'
        elif len(d) >= 6:
            line, new = L['same_last6'], 'card_full'
        elif len(d) >= 4:
            line, new = L['same_last4'].replace('{last4}', digits_say(d[-4:])), 'card_last6'
        else:
            line, new = L['same_name'].replace('{name}', found[0]['name'] or 'Bu'), 'card_last4'
        if new == vars.get('step') and new != 'card':
            fail(line)
        else:
            say(line, new)

    vars['route'] = ''
    if not ok('week_get'):
        close('close_week_error')
    else:
        w = load('wk', 'week_get_response.data.data.')
        cur = int(num(w.get('statementWeek')))
        vars['cur_week'] = cur
        vars['stmt_day'] = int(num(w.get('statementDay')))
        rel = str(w.get('relationType') or '')
        other = safe_name(w.get('relatedCardProductName'))
        vars['relation'] = rel
        vars['related_name'] = other
        name = vars.get('card_name') or 'Sonu ' + digits_say(vars.get('card_last4')) + ' ile biten'
        line = (L['week_state'].replace('{name}', name).replace('{week}', str(cur))
                .replace('{cut}', say_date(w.get('nextStatementDate'))).replace('{due}', say_date(w.get('nextLastPayDate'))))
        if rel == 'M' and other:
            line = line + ' ' + L['week_joint_main'].replace('{other}', other)
        elif rel == 'C' and other:
            line = line + ' ' + L['week_joint_linked'].replace('{other}', other)
        line = line + ' ' + L['week_limit']
        want = int(num(vars.get('want_week')))
        if want in WEEKS and want != cur:
            vars['new_week'] = want
            vars['week_state_line'] = line
            close('decide')
        else:
            say(line + ' ' + week_options(), 'week_pick')
    pass
except Exception as exc:
    vars['route'] = 'close_week_error'
    vars['say_turn'] = 'no'
    vars['week_prep_code_error'] = repr(exc)[:300]

